import{at as e,it as t,t as n,yt as r}from"./chunks/framework.Dyi9RH6t.js";var i=JSON.parse('{"title":"WarpDrive\'s Types Strategy","description":"Understand why WarpDrive brands classes with a `Type` symbol and passes them as generics to `findRecord` instead of using type registries or class tokens.","frontmatter":{"description":"Understand why WarpDrive brands classes with a `Type` symbol and passes them as generics to `findRecord` instead of using type registries or class tokens."},"headers":[],"relativePath":"guides/the-manual/typescript/why-brands.md","filePath":"guides/the-manual/typescript/why-brands.md"}'),a={name:`guides/the-manual/typescript/why-brands.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="warpdrive-s-types-strategy" tabindex="-1">WarpDrive&#39;s Types Strategy <a class="header-anchor" href="#warpdrive-s-types-strategy" aria-label="Permalink to “WarpDrive&#39;s Types Strategy”">​</a></h1><p>If you previously used the EmberData types provided by DefinitelyTyped, one MASSIVE difference you will notice immediately is that WarpDrive does not use any registries for types.</p><p>Instead, WarpDrive uses Symbol keys to brand objects with additional type information.</p><p>For example:</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Model, { attr } </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@warp-drive/legacy/model&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { Type } </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@warp-drive/core/types/symbols&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> default</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> User</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> extends</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  @attr </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">declare</span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;"> name</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [Type] </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;user&#39;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> as</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>This means that when calling an API that takes in a resource type, we pass this branded class as a generic instead of relying on registries. For example:</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> User </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;my-app/models/user&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// ...</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> user</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> store.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">findRecord</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">User</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;user&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>We chose this direction over registries or objects for a number of reasons we&#39;ll detail below.</p><h3 id="why-not-registries" tabindex="-1">Why not registries? <a class="header-anchor" href="#why-not-registries" aria-label="Permalink to “Why not registries?”">​</a></h3><p>We found registries had 5 significant drawbacks.</p><p>First, registries have a max number of entries before TypeScript begins resolving unions based on the registry as <code>any</code>. This limit is relatively low (in the hundreds) so many applications hit into this relatively quickly.</p><p>Second, constructing registries is brittle. Conflicts often arise when attempting to source models from additional libraries, and often result in <code>never</code> types due to an empty registry.</p><p>Third, we couldn&#39;t type WarpDrive itself using registries without adopting extreme complexity. This is because while DefinitelyTyped could assume one single global registry, WarpDrive cannot. This arises for a myriad of reasons: WarpDrive supports multiple stores, multiple sources of schema, and our own test suite defines Models for each test that would conflict with each other if we were forced to use a single global registry.</p><p>Fourth, and possibly most importantly, registries assume that for a given resource-type (like <code>&#39;user&#39;</code>) that only a single type signature exists. While this has <em>mostly</em> been true historically in WarpDrive, it is no longer true and will become increasingly less true as we roll out additional features we have planned. Supporting different type signatures for Create/Edit/Delete as well as for partials and actions means if we stuck with registries, we&#39;d need tons of them and things would get complicated quickly.</p><p>Fifth, the registry approach prevents static analysis from easily determining where in the application a Model or Schema is in use, making it difficult for bundlers to optimize while code-splitting.</p><h3 id="ok-so-then-why-not-objects" tabindex="-1">Ok, so then why not objects? <a class="header-anchor" href="#ok-so-then-why-not-objects" aria-label="Permalink to “Ok, so then why not objects?”">​</a></h3><p>A common alternative to registries is to pass classes as tokens into an API. For instance, we could have redesigned WarpDrive to take a class instead of a string in the call to <code>findRecord</code> below.</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> User </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;my-app/models/user&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// ...</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> user</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> store.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">findRecord</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(User, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>There are two significant drawbacks to this approach. The first is one of the same reasons as &quot;why not registries&quot;: we expect that lots of type signatures will satisfy a single resource-type in the future.</p><p>The second is related and more important: it forces you to use classes or other objects to represent data, which we don&#39;t want to do.</p><p>In the near future, WarpDrive will switch the default story for presenting data from <code>Model</code> which is a class-per-resource approach to <code>ReactiveResource</code>, which is a single class capable of presenting the data for any associated schema. Schema&#39;s are defined in <code>json</code> and can be loaded into the app in any number of ways. That means when using ReactiveResource, there never would be a class to import and use as a token for such a call.</p><h3 id="ok-brands" tabindex="-1">Ok, Brands! <a class="header-anchor" href="#ok-brands" aria-label="Permalink to “Ok, Brands!”">​</a></h3><p>Brands solve the various issues mentioned above, and a bit more!</p><p>Over time, they should enable us to curate a great experience for working with partials, actions, constrained edit signatures, query syntaxes like GraphQL and more.</p>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};